static void controller_component_eventqueue_init(controller_component_eventqueue * eq, controller_component_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer controller_component_eventqueue_size(controller_component_eventqueue * eq)
{
	return eq->size;
}

static controller_component_event controller_component_eventqueue_pop(controller_component_eventqueue * eq)
{
	controller_component_event event;
	if(controller_component_eventqueue_size(eq) <= 0) {
		controller_component_event_init(&event, Controller_Component_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean controller_component_eventqueue_push(controller_component_eventqueue * eq, controller_component_event ev)
{
	if(controller_component_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
